import json
import numpy as np

F = [lambda x: x, lambda x: 1-x]
w = np.array([0.5, 0.5], dtype=float)

def update(w, x, y):
    d = len(w)
    e = np.array([int(f(x) != y) for f in F], dtype=float)
    r = np.zeros((d, d))
    for i in range(d):
        for j in range(d):
            if i != j:
                r[i, j] = max(e[i]-e[j], 0.0)*(1.0+w[i]*w[j])/(d-1)
    nxt = w.copy()
    for i in range(d):
        for j in range(d):
            if i != j:
                nxt[i] += w[j]*(1.0-w[i])*r[j, i] - w[i]*(1.0-w[j])*r[i, j]
    return nxt

def predict(w, x):
    p = np.zeros(2)
    for i, f in enumerate(F):
        p[f(x)] += w[i]
    return p

def rounded(a):
    return [round(float(z), 6) for z in a]

w = update(w, 1, 1)
first = rounded(w)
unseen = rounded(predict(w, 0))
w = update(w, 1, 0)
result = {'after_one': first, 'unseen_distribution': unseen, 'after_reversal': rounded(w), 'mass': round(float(w.sum()), 6)}
print(json.dumps(result, sort_keys=True))
